nodes.command:
node -e "
const fs = require('fs');
const yaml = require('yaml');
const zonePath = '${inputs.project_root}/src/data/zones/${inputs.zone_id}.yaml';
let content = fs.readFileSync(zonePath, 'utf-8');
let doc = yaml.parse(content);

// 初始化白盒配置
doc.whitebox = doc.whitebox || {};
doc.whitebox.objects = doc.whitebox.objects || [];

// 检查物件是否已存在
const existingIdx = doc.whitebox.objects.findIndex(o => o.id === '${inputs.object_id}');
const newObj = {
  id: '${inputs.object_id}',
  name: '${inputs.object_name}',
  type: '${inputs.object_type}',
  icon: '${nodes.intake.output.icon}',
  position: { x: ${inputs.position_x}, y: ${inputs.position_y} },
  billboard: { type: 'object', style: '${inputs.object_type}' }
};

if (existingIdx >= 0) {
  doc.whitebox.objects[existingIdx] = newObj;
  console.log('Updated object:', '${inputs.object_id}');
} else {
  doc.whitebox.objects.push(newObj);
  console.log('Added object:', '${inputs.object_id}');
}

doc.meta = doc.meta || {};
doc.meta.updated_at = new Date().toISOString();
fs.writeFileSync(zonePath, yaml.stringify(doc));
"
